import decimal
import datetime
from decimal import Decimal, ROUND_HALF_UP, ROUND_FLOOR

_CTX = decimal.Context(prec=200000, rounding=ROUND_HALF_UP,
                       Emax=decimal.MAX_EMAX, Emin=decimal.MIN_EMIN)


def _dscale(v):
    e = v.as_tuple().exponent
    if isinstance(e, int) and e < 0:
        return -e
    return 0


def _adddays(dt, days, tz):
    # adempiere.adddays: t + interval '1 second' * (86400*days)  (elapsed time)
    if dt is None or days is None:
        return None
    f = float(_CTX.multiply(Decimal(86400), days))  # numeric -> float8
    us = round(1000000.0 * f)  # interval_mul uses rint (half-even)
    utc = dt.astimezone(datetime.timezone.utc) + datetime.timedelta(microseconds=us)
    return utc.astimezone(tz)


def _local_date(dt, tz):
    if dt is None:
        return None
    return dt.astimezone(tz).date()


def _pg_div100(num, num_dscale):
    # PostgreSQL numeric division by 100 using select_div_scale rules
    if num == 0:
        weight1 = 0
        first1 = 0
    else:
        a = abs(num)
        weight1 = a.adjusted() // 4
        first1 = int(a.scaleb(-4 * weight1, context=_CTX).to_integral_value(rounding=ROUND_FLOOR))
    weight2 = 0
    first2 = 100
    qweight = weight1 - weight2
    if first1 <= first2:
        qweight -= 1
    rscale = 16 - qweight * 4
    rscale = max(rscale, num_dscale, 0, 0)
    rscale = min(rscale, 1000)
    q = num.scaleb(-2, context=_CTX)
    r = q.quantize(Decimal(1).scaleb(-rscale), rounding=ROUND_HALF_UP, context=_CTX)
    if r == 0:
        r = r.copy_abs()
    return r


def _pg_round(v, s):
    s = max(min(s, 2000), -2000)
    if s >= 0:
        r = v.quantize(Decimal(1).scaleb(-s), rounding=ROUND_HALF_UP, context=_CTX)
    else:
        r = v.quantize(Decimal(1).scaleb(-s), rounding=ROUND_HALF_UP, context=_CTX)
        r = r.quantize(Decimal(1), context=_CTX)
    if r == 0:
        r = r.copy_abs()
    return r


def _client_country(data, client):
    best = None
    for cl in data.select('ad_client', ad_client_id=client):
        for l in data.select('ad_language', ad_language=cl.get('ad_language')):
            cc = l.get('countrycode')
            if cc is None:
                continue
            for co in data.select('c_country', countrycode=cc):
                cid = co.get('c_country_id')
                if cid is None:
                    continue
                if best is None or cid > best:
                    best = cid
    if best is None:
        best = Decimal(100)
    return best


def _nextbusinessday(d, client, data):
    if d is None:
        return None
    country = _client_country(data, client)
    one = datetime.timedelta(days=1)
    while True:
        wd = d.isoweekday()  # Mon=1..Sun=7
        if wd == 6:
            d = d + datetime.timedelta(days=2)
        elif wd == 7:
            d = d + one
        is_holiday = False
        start = datetime.datetime(d.year, d.month, d.day)
        rows = []
        for r in data.select('c_nonbusinessday', ad_client_id=client, isactive='Y'):
            d1 = r.get('date1')
            if d1 is None:
                continue
            if not isinstance(d1, datetime.datetime):
                d1 = datetime.datetime(d1.year, d1.month, d1.day)
            if d1 < start:
                continue
            c = r.get('c_country_id')
            if c is None:
                c = Decimal(0)
            if not (c == 0 or c == country):
                continue
            rows.append(d1)
        rows.sort()
        for d1 in rows:
            if d != d1.date():
                break
            d = d + one
            is_holiday = True
        if not is_holiday:
            break
    return d


def paymenttermdiscount(amount, currency_id, paymentterm_id, docdate, paydate, *, data):
    tz = data.session_tz

    v_currency = currency_id
    if v_currency is not None and v_currency == 0:
        best = None
        for pt in data.select('c_paymentterm', c_paymentterm_id=paymentterm_id):
            client = pt.get('ad_client_id')
            if not data.select('ad_clientinfo', ad_client_id=client):
                continue
            for s in data.select('c_acctschema', ad_client_id=client):
                cid = s.get('c_currency_id')
                if cid is None:
                    continue
                if best is None or cid > best:
                    best = cid
        v_currency = best if best is not None else Decimal(0)

    v_precision = None
    for row in data.select('c_currency', c_currency_id=v_currency):
        v_precision = row.get('stdprecision')

    v_min = None
    if v_precision is not None:
        if v_precision == v_precision.to_integral_value():
            v_min = Decimal(1).scaleb(-int(v_precision), context=_CTX)
        else:
            v_min = _CTX.divide(Decimal(1), _CTX.power(Decimal(10), v_precision))

    if amount is None or paymentterm_id is None or docdate is None:
        return Decimal(0)

    discount = Decimal(0)
    pay_d = _local_date(paydate, tz)

    for p in data.select('c_paymentterm', c_paymentterm_id=paymentterm_id):
        grace = p.get('gracedays')
        t1 = _adddays(_adddays(docdate, p.get('discountdays'), tz), grace, tz)
        t2 = _adddays(_adddays(docdate, p.get('discountdays2'), tz), grace, tz)
        d1 = _local_date(t1, tz)
        d2 = _local_date(t2, tz)

        nbd = p.get('isnextbusinessday')
        if nbd is not None and nbd.rstrip() == 'Y':
            d1 = _nextbusinessday(d1, p.get('ad_client_id'), data)
            d2 = _nextbusinessday(d2, p.get('ad_client_id'), data)

        if d1 is not None and pay_d is not None and d1 >= pay_d:
            pct = p.get('discount')
            if pct is None:
                discount = None
            else:
                prod = _CTX.multiply(amount, pct)
                discount = _pg_div100(prod, _dscale(amount) + _dscale(pct))
        elif d2 is not None and pay_d is not None and d2 >= pay_d:
            pct = p.get('discount2')
            if pct is None:
                discount = None
            else:
                prod = _CTX.multiply(amount, pct)
                discount = _pg_div100(prod, _dscale(amount) + _dscale(pct))

    if discount is not None and v_min is not None:
        if discount > -v_min and discount < v_min:
            discount = Decimal(0)

    if discount is None:
        discount = Decimal(0)
    if v_precision is None:
        return None
    scale = int(v_precision.to_integral_value(rounding=ROUND_HALF_UP))
    return _pg_round(discount, scale)
